using Barotrauma;
using Microsoft.Xna.Framework;

namespace SOS
{
    public enum SizingMode
    {
        Fixed,       // Ocupa un porcentaje estricto del ancho disponible
        FitContent,  // Mide el contenido y se ajusta hasta una proporción máxima
        Flexible     // Reclama todo el espacio sobrante disponible
    }

    public class ColumnConfig
    {
        public GUIComponent Component { get; }
        public SizingMode Sizing { get; set; }
        public float Ratio { get; set; }
        public int MinWidth { get; set; }
        public int MaxWidth { get; set; }

        // Delegates de medición desacoplados
        public Func<GUIComponent, int>? CustomMeasureWidth { get; set; }
        public Func<GUIComponent, int>? CustomMeasureHeight { get; set; }

        public ColumnConfig(
            GUIComponent component,
            SizingMode sizing = SizingMode.Flexible,
            float ratio = 0.5f,
            int minWidth = 0,
            int maxWidth = int.MaxValue,
            Func<GUIComponent, int>? customMeasureWidth = null,
            Func<GUIComponent, int>? customMeasureHeight = null)
        {
            Component = component;
            Sizing = sizing;
            Ratio = ratio;
            MinWidth = minWidth;
            MaxWidth = maxWidth;
            CustomMeasureWidth = customMeasureWidth;
            CustomMeasureHeight = customMeasureHeight;
        }

        public int MeasureWidth()
        {
            if (Component == null) return 0;
            if (CustomMeasureWidth != null) return CustomMeasureWidth(Component);

            if (Component is GUITextBlock textBlock)
            {
                Vector2 size = textBlock.Font.MeasureString(textBlock.Text);
                return (int)Math.Ceiling(size.X * textBlock.TextScale) + 6;
            }
            return Component.RectTransform.NonScaledSize.X;
        }

        public int MeasureHeight()
        {
            if (Component == null) return 0;
            if (CustomMeasureHeight != null) return CustomMeasureHeight(Component);

            if (Component is GUITextBlock textBlock)
            {
                return (int)Math.Ceiling(textBlock.TextSize.Y);
            }
            return Component.RectTransform.NonScaledSize.Y;
        }
    }

    // Corregido: Hereda de GUIFrame para actuar estrictamente como un contenedor ligero (Solución SRP)
    public class GUIDynamicRow : GUIFrame
    {
        private readonly ColumnConfig _left;
        private readonly ColumnConfig _right;
        private readonly int _spacing;
        private int _lastWidth = -1;

        public GUIDynamicRow(RectTransform rectT, ColumnConfig left, ColumnConfig right, int spacing = 10)
            : base(rectT, style: null)
        {
            _left = left;
            _right = right;
            _spacing = spacing;
            CanBeFocused = false;

            if (_left.Component != null)
            {
                _left.Component.RectTransform.Parent = RectTransform;
                _left.Component.RectTransform.Anchor = Anchor.TopLeft;
                _left.Component.RectTransform.Pivot = Pivot.TopLeft;
            }
            if (_right.Component != null)
            {
                _right.Component.RectTransform.Parent = RectTransform;
                _right.Component.RectTransform.Anchor = Anchor.TopRight;
                _right.Component.RectTransform.Pivot = Pivot.TopRight;
            }

            RectTransform.SizeChanged += RecalculateLayout;
        }

        public void RecalculateLayout()
        {
            int totalWidth = Rect.Width;
            if (totalWidth <= 0 ||
                totalWidth < 120 ||
                totalWidth == _lastWidth) return;

            _lastWidth = totalWidth;

            int availableWidth = totalWidth - _spacing;
            if (availableWidth <= 0) return;
            int rightWidth = 0;

            if (_right.Sizing == SizingMode.Fixed)
            {
                rightWidth = (int)(availableWidth * _right.Ratio);
            }
            else if (_right.Sizing == SizingMode.FitContent)
            {
                int preferred = _right.MeasureWidth();
                int maxLimit = (int)(availableWidth * _right.Ratio);
                rightWidth = Math.Min(preferred, maxLimit);
            }
            rightWidth = MathHelper.Clamp(rightWidth, _right.MinWidth, _right.MaxWidth);


            int leftWidth;
            if (_left.Sizing == SizingMode.Fixed)
            {
                leftWidth = (int)(availableWidth * _left.Ratio);
            }
            else if (_left.Sizing == SizingMode.FitContent)
            {
                int preferred = _left.MeasureWidth();
                int maxLimit = (int)(availableWidth * _left.Ratio);
                leftWidth = Math.Min(preferred, maxLimit);
            }
            else // Flexible
            {
                leftWidth = availableWidth - rightWidth;
            }
            leftWidth = MathHelper.Clamp(leftWidth, _left.MinWidth, _left.MaxWidth);

            if (leftWidth + rightWidth > availableWidth)
            {
                rightWidth = availableWidth - leftWidth;
                rightWidth = MathHelper.Clamp(rightWidth, _right.MinWidth, _right.MaxWidth);
            }

            if (_left.Component != null)
            {
                _left.Component.RectTransform.NonScaledSize = new Point(leftWidth, Rect.Height);
                _left.Component.RectTransform.RecalculateChildren(true, true);
            }

            if (_right.Component != null)
            {
                _right.Component.RectTransform.NonScaledSize = new Point(rightWidth, Rect.Height);
                _right.Component.RectTransform.RecalculateChildren(true, true);
            }

            int leftHeight = _left.MeasureHeight();
            int rightHeight = _right.MeasureHeight();
            int requiredHeight = Math.Max(20, Math.Max(leftHeight, rightHeight) + 4);

            if (RectTransform.MinSize.Y != requiredHeight)
            {
                RectTransform.MinSize = new Point(0, requiredHeight);
                RectTransform.MaxSize = new Point(int.MaxValue, requiredHeight);

                if (Parent is GUILayoutGroup parentGroup)
                {
                    RecalculateParentGroupHeight(parentGroup);
                }
            }
        }

        public static void RecalculateParentGroupHeight(GUILayoutGroup? layoutGroup)
        {
            if (layoutGroup == null) return;
            int totalHeight = 0;
            foreach (var child in layoutGroup.Children)
            {
                if (child.Visible)
                {
                    totalHeight += child.Rect.Height + layoutGroup.AbsoluteSpacing;
                }
            }
            totalHeight += 10; // Padding inferior
            layoutGroup.RectTransform.MinSize = new Point(0, totalHeight);
            layoutGroup.RectTransform.MaxSize = new Point(int.MaxValue, totalHeight);
            layoutGroup.ForceLayoutRecalculation();
        }
    }
}